javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {

    if (((api.state.currChoice == "Forever") && (api.state.showSelect != ""))) {
        return {
            items: [{
                message: "Retention period is unchanged",
                type: "error"
            }]
        };
    } else if (((api.state.prevChoice == "") && (api.state.prevChoice == "")) || ((api.state.prevChoice == undefined) && (api.state.prevChoice == undefined))) {
        {
            if (api.state.showSelect == "SHOWSELECT") {

                return {
                    items: [{
                        message: "Retention period is Unchanged",
                        type: "error"
                    }]
                };
            }
        }

    }
})

